              "position": 2,
              "name": categoryMatch.name,
              "item": `https://zeroapitools.vercel.app/?cat=${tool.category}`
            },
            {
              "@type": "ListItem",
              "position": 3,
              "name": tool.name,
              "item": `https://zeroapitools.vercel.app/${currentTool}`
            }
          ]
        });
      }
