  const map = { text: 'Text & String', code: 'Code', converter: 'Converter', css: 'CSS', image: 'Image', security: 'Security', seo: 'SEO', unique: 'Γ£¿ Unique', calculator: 'Calculators', pdf: 'PDF Tools' };
  return map[cat] || cat;
}

