import React, { useState } from 'react';

export default function AgeCalculator({ copyToClipboard, showToast }) {
  const [dob, setDob] = useState('');
  const [toDate, setToDate] = useState(new Date().toISOString().split('T')[0]);

  const calc = (() => {
    if (!dob) return null;
    const birth = new Date(dob);
    const target = new Date(toDate);
    if (isNaN(birth.getTime()) || isNaN(target.getTime())) return null;
    if (birth > target) return null;

    let years = target.getFullYear() - birth.getFullYear();
    let months = target.getMonth() - birth.getMonth();
    let days = target.getDate() - birth.getDate();

    if (days < 0) {
      months--;
      const prevMonth = new Date(target.getFullYear(), target.getMonth(), 0);
      days += prevMonth.getDate();
    }
    if (months < 0) { years--; months += 12; }

    const totalDays = Math.floor((target - birth) / (1000 * 60 * 60 * 24));
    const totalWeeks = Math.floor(totalDays / 7);
    const totalMonths = years * 12 + months;
    const totalHours = totalDays * 24;
    const heartbeats = totalHours * 60 * 70;

    // Next birthday
    const nextBday = new Date(target.getFullYear(), birth.getMonth(), birth.getDate());
    if (nextBday <= target) nextBday.setFullYear(target.getFullYear() + 1);
    const daysToNextBday = Math.ceil((nextBday - target) / (1000 * 60 * 60 * 24));

    const dayNames = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
    const birthDay = dayNames[birth.getDay()];
    const zodiac = getZodiac(birth.getMonth() + 1, birth.getDate());
    return { years, months, days, totalDays, totalWeeks, totalMonths, totalHours, heartbeats, daysToNextBday, birthDay, zodiac };
  })();

  function getZodiac(month, day) {
    const signs = [
      [1, 20, 'Capricorn ΓÖæ'], [2, 19, 'Aquarius ΓÖÆ'], [3, 20, 'Pisces ΓÖô'],
      [4, 20, 'Aries ΓÖê'], [5, 21, 'Taurus ΓÖë'], [6, 21, 'Gemini ΓÖè'],
      [7, 22, 'Cancer ΓÖï'], [8, 23, 'Leo ΓÖî'], [9, 23, 'Virgo ΓÖì'],
      [10, 23, 'Libra ΓÖÄ'], [11, 22, 'Scorpio ΓÖÅ'], [12, 22, 'Sagittarius ΓÖÉ'], [12, 31, 'Capricorn ΓÖæ']
    ];
    for (const [m, d, sign] of signs) {
      if (month < m || (month === m && day <= d)) return sign;
    }
    return 'Capricorn ΓÖæ';
  }

  const fmtNum = n => n.toLocaleString('en-IN');

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 20 }}>
      <div className="pane">
        <div className="pane-header"><span className="pane-title">Enter Dates</span></div>
        <div className="pane-body" style={{ gap: 16 }}>
          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 16 }}>
            <div>
              <label className="input-label">Date of Birth</label>
              <input className="input-field" type="date" value={dob} onChange={e => setDob(e.target.value)} max={toDate} />
            </div>
            <div>
              <label className="input-label">Calculate Age As Of</label>
              <input className="input-field" type="date" value={toDate} onChange={e => setToDate(e.target.value)} />
            </div>
          </div>
          <div style={{ display: 'flex', gap: 8 }}>
            <button className="btn btn-ghost btn-sm" onClick={() => setToDate(new Date().toISOString().split('T')[0])}>Today</button>
          </div>
        </div>
      </div>

      {calc && (
        <>
          {/* Main Age Display */}
          <div className="pane" style={{ background: 'var(--accent-purple-dim)', borderColor: 'var(--accent-purple)' }}>
            <div className="pane-body" style={{ textAlign: 'center', padding: '28px 20px' }}>
              <div style={{ fontSize: 13, color: 'var(--text-muted)', marginBottom: 12, textTransform: 'uppercase', letterSpacing: 1 }}>Your Age</div>
              <div style={{ display: 'flex', justifyContent: 'center', gap: 24, flexWrap: 'wrap' }}>
                {[
                  { val: calc.years, label: 'Years' },
                  { val: calc.months, label: 'Months' },
                  { val: calc.days, label: 'Days' },
                ].map(({ val, label }) => (
                  <div key={label} style={{ textAlign: 'center' }}>
                    <div style={{ fontSize: 52, fontWeight: 900, color: 'var(--accent-purple-light)', lineHeight: 1, fontFamily: 'Space Grotesk, sans-serif' }}>{val}</div>
                    <div style={{ fontSize: 13, color: 'var(--text-muted)', marginTop: 4 }}>{label}</div>
                  </div>
                ))}
              </div>
            </div>
          </div>

          {/* Stats Grid */}
          <div className="stats-row" style={{ flexWrap: 'wrap' }}>
            {[
              { label: 'Total Days Lived', val: fmtNum(calc.totalDays), color: 'var(--accent-cyan)' },
              { label: 'Total Weeks', val: fmtNum(calc.totalWeeks), color: 'var(--accent-emerald)' },
              { label: 'Total Months', val: fmtNum(calc.totalMonths), color: 'var(--accent-amber)' },
              { label: 'Total Hours', val: fmtNum(calc.totalHours), color: 'var(--text-secondary)' },
              { label: '≡ƒÆô Heartbeats Est.', val: fmtNum(calc.heartbeats), color: 'var(--accent-rose)' },
              { label: '≡ƒÄé Days to Birthday', val: `${fmtNum(calc.daysToNextBday)} days`, color: 'var(--accent-purple-light)' },
            ].map(({ label, val, color }) => (
              <div key={label} className="stat-card" style={{ flex: '1 1 150px' }}>
                <div className="stat-label">{label}</div>
                <div className="stat-value" style={{ color, fontSize: 18 }}>{val}</div>
              </div>
            ))}
          </div>

          {/* Fun Facts */}
          <div className="pane">
            <div className="pane-header"><span className="pane-title">Fun Facts</span></div>
            <div className="pane-body" style={{ gap: 10 }}>
              {[
                { icon: '≡ƒôà', label: 'Born on', val: calc.birthDay },
                { icon: 'Γ¡É', label: 'Zodiac Sign', val: calc.zodiac },
                { icon: '≡ƒÄé', label: 'Next Birthday', val: `${calc.daysToNextBday} days away` },
              ].map(({ icon, label, val }) => (
                <div key={label} style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '10px 14px', background: 'var(--bg-primary)', borderRadius: 8, border: '1px solid var(--border-primary)' }}>
                  <span style={{ color: 'var(--text-muted)', fontSize: 13 }}>{icon} {label}</span>
                  <strong style={{ color: 'var(--text-heading)', fontSize: 14 }}>{val}</strong>
                </div>
              ))}
            </div>
          </div>
        </>
      )}
      {dob && !calc && <div style={{ textAlign: 'center', color: 'var(--accent-rose)', padding: 20 }}>ΓÜá Invalid dates or Date of birth cannot be after the target date</div>}
    </div>
  );
}

import React, { useState, useMemo } from 'react';

const formatINR = (val) =>
  new Intl.NumberFormat('en-IN', {
    style: 'currency',
    currency: 'INR',
    maximumFractionDigits: 0,
  }).format(val);

const FREQUENCIES = [
  { label: 'Monthly', value: 12 },
  { label: 'Quarterly', value: 4 },
  { label: 'Half-Yearly', value: 2 },
  { label: 'Yearly', value: 1 },
];

function DonutChart({ principal, interest, size = 180 }) {
  const total = principal + interest;
  if (total === 0) return null;
  const principalPct = principal / total;
  const radius = 70;
  const cx = size / 2;
  const cy = size / 2;
  const stroke = 28;
  const circumference = 2 * Math.PI * radius;
  const principalDash = circumference * principalPct;
  const interestDash = circumference * (1 - principalPct);

  return (
    <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 12 }}>
      <svg width={size} height={size} viewBox={`0 0 ${size} ${size}`}>
        {/* Interest arc */}
        <circle
          cx={cx}
          cy={cy}
          r={radius}
          fill="none"
          stroke="var(--accent-purple)"
          strokeWidth={stroke}
          strokeDasharray={`${interestDash} ${circumference}`}
          strokeDashoffset={0}
          transform={`rotate(-90 ${cx} ${cy})`}
          style={{ transition: 'stroke-dasharray 0.5s ease' }}
        />
        {/* Principal arc */}
        <circle
          cx={cx}
          cy={cy}
          r={radius}
          fill="none"
          stroke="var(--accent-rose)"
          strokeWidth={stroke}
          strokeDasharray={`${principalDash} ${circumference}`}
          strokeDashoffset={-interestDash}
          transform={`rotate(-90 ${cx} ${cy})`}
          style={{ transition: 'stroke-dasharray 0.5s ease' }}
        />
        <text x={cx} y={cy - 8} textAnchor="middle" fill="var(--text-heading)" fontSize="14" fontWeight="700">
          {formatINR(total)}
        </text>
        <text x={cx} y={cy + 12} textAnchor="middle" fill="var(--text-muted)" fontSize="11">
          Maturity Amount
        </text>
      </svg>
      <div style={{ display: 'flex', gap: 20 }}>
        <span style={{ display: 'flex', alignItems: 'center', gap: 6, fontSize: 12, color: 'var(--text-muted)' }}>
          <span style={{ width: 10, height: 10, borderRadius: '50%', background: 'var(--accent-rose)', display: 'inline-block' }} />
          Principal
        </span>
        <span style={{ display: 'flex', alignItems: 'center', gap: 6, fontSize: 12, color: 'var(--text-muted)' }}>
          <span style={{ width: 10, height: 10, borderRadius: '50%', background: 'var(--accent-purple)', display: 'inline-block' }} />
          Interest
        </span>
      </div>
    </div>
  );
}

export default function CompoundInterestCalc({ copyToClipboard, showToast }) {
  const [principal, setPrincipal] = useState(100000);
  const [rate, setRate] = useState(8);
  const [timePeriod, setTimePeriod] = useState(5);
  const [frequency, setFrequency] = useState(12);
  const [showTable, setShowTable] = useState(false);

  const results = useMemo(() => {
    const P = Number(principal) || 0;
    const annualRate = Number(rate) || 0;
    const t = Number(timePeriod) || 0;
    const n = Number(frequency);
    const r = annualRate / 100;

    // A = P(1 + r/n)^(nt)
    let maturityAmount = 0;
    if (P > 0 && t > 0) {
      maturityAmount = P * Math.pow(1 + r / n, n * t);
    }

    const totalInterest = maturityAmount - P;

    // Year-by-year breakdown
    const yearlyData = [];
    for (let y = 1; y <= t; y++) {
      const amount = P * Math.pow(1 + r / n, n * y);
      const interest = amount - P;
      const prevAmount = y === 1 ? P : P * Math.pow(1 + r / n, n * (y - 1));
      const yearInterest = amount - prevAmount;
      yearlyData.push({
        year: y,
        openingBalance: prevAmount,
        interestEarned: yearInterest,
        closingBalance: amount,
        totalInterest: interest,
      });
    }

    return { principal: P, totalInterest, maturityAmount, yearlyData };
  }, [principal, rate, timePeriod, frequency]);

  const selectedFreqLabel = FREQUENCIES.find((f) => f.value === frequency)?.label || 'Monthly';

  const handleCopyResults = () => {
    const text = `Compound Interest Calculator Results\nΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöü\nPrincipal: ${formatINR(results.principal)}\nAnnual Rate: ${rate}%\nTime Period: ${timePeriod} years\nCompounding: ${selectedFreqLabel}\n\nTotal Interest: ${formatINR(results.totalInterest)}\nMaturity Amount: ${formatINR(results.maturityAmount)}`;
    copyToClipboard(text);
    showToast('Results copied to clipboard!');
  };

  return (
    <div className="pane" style={{ maxWidth: 900, margin: '0 auto' }}>
      <div className="pane-header">
        <span className="pane-title" style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
          <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="var(--accent-rose)" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
            <line x1="12" y1="1" x2="12" y2="23" />
            <path d="M17 5H9.5a3.5 3.5 0 0 0 0 7h5a3.5 3.5 0 0 1 0 7H6" />
          </svg>
          Compound Interest Calculator
        </span>
        <button className="btn btn-sm" onClick={handleCopyResults}>
          Copy Results
        </button>
      </div>

      <div className="pane-body">
        <div className="split-pane">
          {/* Left: Inputs */}
          <div style={{ display: 'flex', flexDirection: 'column', gap: 20 }}>
            <div className="input-field">
              <label className="input-label">Principal Amount (Γé╣)</label>
              <input
                type="number"
                value={principal}
                onChange={(e) => setPrincipal(Math.max(0, Number(e.target.value)))}
                min={0}
                step={10000}
                style={{
                  width: '100%',
                  padding: '10px 14px',
                  background: 'var(--bg-primary)',
                  border: '1px solid var(--bg-elevated)',
                  borderRadius: 8,
                  color: 'var(--text-heading)',
                  fontSize: 15,
                  fontFamily: 'var(--font-mono)',
                }}
              />
            </div>

            <div className="input-field">
              <label className="input-label">Annual Interest Rate (%)</label>
              <input
                type="number"
                value={rate}
                onChange={(e) => setRate(Math.max(0, Math.min(100, Number(e.target.value))))}
                min={0}
                max={100}
                step={0.25}
                style={{
                  width: '100%',
                  padding: '10px 14px',
                  background: 'var(--bg-primary)',
                  border: '1px solid var(--bg-elevated)',
