              {formatINR(results.principal)}
            </div>
            <div style={{ fontSize: 11, color: 'var(--text-muted)', marginTop: 4 }}>
              Initial investment
            </div>
          </div>
          <div className="stat-card" style={{ borderLeft: '3px solid var(--accent-purple)' }}>
