          <div className="tab-group">
            <button className={`tab-btn ${mode === 'add' ? 'active' : ''}`} onClick={() => setMode('add')}>Γ₧ò Add GST (Exclusive)</button>
            <button className={`tab-btn ${mode === 'extract' ? 'active' : ''}`} onClick={() => setMode('extract')}>Γ₧û Extract GST (Inclusive)</button>
