      {/* Quick Examples */}
      <div className="pane">
        <div className="pane-header"><span className="pane-title">Quick Examples</span></div>
        <div className="pane-body" style={{ gap: 8 }}>
          {[
            { label: '18% GST on Γé╣1000', a: '18', b: '1000', mode: 'percent-of' },
            { label: 'Discount: 200 off 800?', a: '200', b: '800', mode: 'what-percent' },
            { label: 'Γé╣50 ΓåÆ Γé╣75 change', a: '50', b: '75', mode: 'percent-change' },
            { label: 'Γé╣5000 + 10% raise', a: '5000', b: '10', mode: 'increase-decrease' },
          ].map(ex => (
            <button key={ex.label} className="btn btn-ghost btn-sm" style={{ justifyContent: 'flex-start', width: '100%', textAlign: 'left' }}
              onClick={() => { setMode(ex.mode); setA(ex.a); setB(ex.b); }}>
              ≡ƒÆí {ex.label}
            </button>
          ))}
        </div>
      </div>
    </div>
  );
}

import React, { useState, useMemo } from 'react';

const formatINR = (val) =>
  new Intl.NumberFormat('en-IN', {
    style: 'currency',
    currency: 'INR',
    maximumFractionDigits: 0,
  }).format(val);

function DonutChart({ invested, returns, size = 180 }) {
  const total = invested + returns;
  if (total === 0) return null;
  const investedPct = invested / total;
  const radius = 70;
  const cx = size / 2;
  const cy = size / 2;
  const stroke = 28;
  const circumference = 2 * Math.PI * radius;
  const investedDash = circumference * investedPct;
  const returnsDash = circumference * (1 - investedPct);

  return (
    <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 12 }}>
      <svg width={size} height={size} viewBox={`0 0 ${size} ${size}`}>
        {/* Returns arc */}
        <circle
          cx={cx}
          cy={cy}
          r={radius}
          fill="none"
          stroke="var(--accent-purple)"
          strokeWidth={stroke}
          strokeDasharray={`${returnsDash} ${circumference}`}
          strokeDashoffset={0}
          transform={`rotate(-90 ${cx} ${cy})`}
          style={{ transition: 'stroke-dasharray 0.5s ease' }}
        />
        {/* Invested arc */}
        <circle
          cx={cx}
          cy={cy}
          r={radius}
          fill="none"
          stroke="var(--accent-rose)"
          strokeWidth={stroke}
          strokeDasharray={`${investedDash} ${circumference}`}
          strokeDashoffset={-returnsDash}
          transform={`rotate(-90 ${cx} ${cy})`}
          style={{ transition: 'stroke-dasharray 0.5s ease' }}
        />
        <text x={cx} y={cy - 8} textAnchor="middle" fill="var(--text-heading)" fontSize="14" fontWeight="700">
          {formatINR(total)}
        </text>
        <text x={cx} y={cy + 12} textAnchor="middle" fill="var(--text-muted)" fontSize="11">
          Total Value
        </text>
      </svg>
      <div style={{ display: 'flex', gap: 20 }}>
        <span style={{ display: 'flex', alignItems: 'center', gap: 6, fontSize: 12, color: 'var(--text-muted)' }}>
          <span style={{ width: 10, height: 10, borderRadius: '50%', background: 'var(--accent-rose)', display: 'inline-block' }} />
          Invested
        </span>
        <span style={{ display: 'flex', alignItems: 'center', gap: 6, fontSize: 12, color: 'var(--text-muted)' }}>
          <span style={{ width: 10, height: 10, borderRadius: '50%', background: 'var(--accent-purple)', display: 'inline-block' }} />
          Returns
        </span>
      </div>
    </div>
  );
}

export default function SipCalculator({ copyToClipboard, showToast }) {
  const [monthlyInvestment, setMonthlyInvestment] = useState(5000);
  const [annualReturn, setAnnualReturn] = useState(12);
  const [years, setYears] = useState(10);
  const [showTable, setShowTable] = useState(false);

  const results = useMemo(() => {
    const P = Number(monthlyInvestment) || 0;
    const annualRate = Number(annualReturn) || 0;
    const n = (Number(years) || 0) * 12;
    const r = annualRate / 12 / 100;

    let totalValue = 0;
    if (r > 0 && n > 0) {
      totalValue = P * (((Math.pow(1 + r, n) - 1) / r) * (1 + r));
    } else if (r === 0) {
      totalValue = P * n;
    }

    const totalInvested = P * n;
    const estimatedReturns = totalValue - totalInvested;

    // Year-by-year breakdown
    const yearlyData = [];
    for (let y = 1; y <= (Number(years) || 0); y++) {
      const months = y * 12;
      let fv = 0;
      if (r > 0) {
        fv = P * (((Math.pow(1 + r, months) - 1) / r) * (1 + r));
      } else {
        fv = P * months;
      }
      const invested = P * months;
      yearlyData.push({
        year: y,
        invested,
        value: fv,
        returns: fv - invested,
      });
    }

    return { totalInvested, estimatedReturns, totalValue, yearlyData };
  }, [monthlyInvestment, annualReturn, years]);

  const handleCopyResults = () => {
    const text = `SIP Calculator Results\nΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöüΓöü\nMonthly Investment: ${formatINR(monthlyInvestment)}\nExpected Return: ${annualReturn}% p.a.\nDuration: ${years} years\n\nTotal Invested: ${formatINR(results.totalInvested)}\nEstimated Returns: ${formatINR(results.estimatedReturns)}\nTotal Value: ${formatINR(results.totalValue)}`;
    copyToClipboard(text);
    showToast('Results copied to clipboard!');
  };

  return (
    <div className="pane" style={{ maxWidth: 900, margin: '0 auto' }}>
      <div className="pane-header">
        <span className="pane-title" style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
          <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="var(--accent-purple)" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
            <polyline points="22 7 13.5 15.5 8.5 10.5 2 17" />
            <polyline points="16 7 22 7 22 13" />
          </svg>
          SIP Calculator
        </span>
        <button className="btn btn-sm" onClick={handleCopyResults}>
          Copy Results
        </button>
      </div>

      <div className="pane-body">
        <div className="split-pane">
          {/* Left: Inputs */}
          <div style={{ display: 'flex', flexDirection: 'column', gap: 20 }}>
            <div className="input-field">
              <label className="input-label">Monthly Investment (Γé╣)</label>
              <input
                type="number"
                value={monthlyInvestment}
                onChange={(e) => setMonthlyInvestment(Math.max(0, Number(e.target.value)))}
                min={0}
                step={500}
                style={{
                  width: '100%',
                  padding: '10px 14px',
                  background: 'var(--bg-primary)',
                  border: '1px solid var(--bg-elevated)',
                  borderRadius: 8,
                  color: 'var(--text-heading)',
                  fontSize: 15,
                  fontFamily: 'var(--font-mono)',
                }}
              />
            </div>

            <div className="input-field">
              <label className="input-label">Expected Annual Return (%)</label>
              <input
                type="number"
                value={annualReturn}
                onChange={(e) => setAnnualReturn(Math.max(0, Math.min(50, Number(e.target.value))))}
                min={0}
                max={50}
                step={0.5}
                style={{
                  width: '100%',
                  padding: '10px 14px',
                  background: 'var(--bg-primary)',
                  border: '1px solid var(--bg-elevated)',
                  borderRadius: 8,
                  color: 'var(--text-heading)',
                  fontSize: 15,
                  fontFamily: 'var(--font-mono)',
                }}
              />
            </div>

            <div className="input-field">
              <label className="input-label">
                Investment Duration: <strong style={{ color: 'var(--accent-purple)' }}>{years} {years === 1 ? 'Year' : 'Years'}</strong>
              </label>
              <input
                type="range"
                className="slider"
                value={years}
                onChange={(e) => setYears(Number(e.target.value))}
                min={1}
                max={40}
                step={1}
