      // Remove whitespace between tags
      html = html.replace(/>\s+</g, '><');

      // Collapse remaining whitespace
      html = html.replace(/\s+/g, ' ');

      return html.trim();
    } catch (e) {
      return 'Error minifying: ' + e.message;
