import React, { useState, useEffect } from 'react';

export default function JsonFormatter({ copyToClipboard, showToast, sampleData }) {
  const [input, setInput] = useState('');
  const [output, setOutput] = useState('');
  const [error, setError] = useState('');

  useEffect(() => { if (sampleData) { setInput(sampleData); parseJson(sampleData); } }, [sampleData]);

  useEffect(() => {
    let script = document.getElementById('faq-schema-json');
    if (!script) {
      script = document.createElement('script');
      script.id = 'faq-schema-json';
      script.type = 'application/ld+json';
      document.head.appendChild(script);
    }
    script.textContent = JSON.stringify({
      "@context": "https://schema.org",
      "@type": "FAQPage",
      "mainEntity": [
        {
          "@type": "Question",
          "name": "Is my JSON data safe?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Yes, absolutely! Our JSON Formatter runs 100% locally in your web browser. Your data is never uploaded to any server or database, making it perfectly safe for sensitive configuration files or API tokens."
          }
        },
        {
          "@type": "Question",
          "name": "What is the difference between JSON beautify and minify?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Beautifying JSON adds indentation and line breaks to make it readable by humans. Minifying JSON removes all unnecessary whitespace to make the payload size as small as possible for network transfers."
          }
        },
        {
          "@type": "Question",
          "name": "How do I fix 'Unexpected token' in JSON?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "The 'Unexpected token' error usually means you have a trailing comma, forgot to quote a key (all keys must be in double quotes), or used single quotes instead of double quotes. Check the exact line and column number provided by our validator."
          }
        }
      ]
    });

    return () => {
      const existingScript = document.getElementById('faq-schema-json');
      if (existingScript) existingScript.remove();
    };
  }, []);

  const parseJson = (text) => {
    try {
      const parsed = JSON.parse(text);
      setError('');
      return parsed;
    } catch (e) {
      const msg = e.message;
      const posMatch = msg.match(/position\s+(\d+)/i);
      let info = msg;
      if (posMatch) {
        const pos = parseInt(posMatch[1], 10);
        const lines = text.substring(0, pos).split('\n');
        const line = lines.length;
        const col = lines[lines.length - 1].length + 1;
        info = `${msg} (Line ${line}, Column ${col})`;
      }
      setError(info);
      return null;
    }
  };

  const handleBeautify = () => {
    if (!input.trim()) {
      setOutput('');
      setError('');
      return;
    }
    const parsed = parseJson(input);
    if (parsed !== null) {
      setOutput(JSON.stringify(parsed, null, 2));
    } else {
      setOutput('');
    }
  };

  const handleMinify = () => {
    if (!input.trim()) {
      setOutput('');
      setError('');
      return;
    }
    const parsed = parseJson(input);
    if (parsed !== null) {
      setOutput(JSON.stringify(parsed));
    } else {
      setOutput('');
    }
  };

  const handleValidate = () => {
    if (!input.trim()) {
      setError('');
      setOutput('');
      showToast('Please enter some JSON to validate');
      return;
    }
    const parsed = parseJson(input);
    if (parsed !== null) {
      setError('');
      setOutput('');
      showToast('Γ£à Valid JSON!');
    }
  };

  const handleCopy = () => {
    if (!output) {
      showToast('Nothing to copy');
      return;
    }
    copyToClipboard(output);
    showToast('Copied to clipboard!');
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 20 }}>
      <div className="split-pane">
      <div className="pane">
        <div className="pane-header">
          <span className="pane-title">JSON Input</span>
          <div className="btn-group">
            <button className="btn btn-primary btn-sm" onClick={handleBeautify}>Beautify</button>
            <button className="btn btn-secondary btn-sm" onClick={handleMinify}>Minify</button>
            <button className="btn btn-success btn-sm" onClick={handleValidate}>Validate</button>
          </div>
        </div>
        <div className="pane-body">
          <textarea
            className="textarea-code"
            value={input}
            onChange={(e) => setInput(e.target.value)}
            placeholder='Paste your JSON here...\n{\n  "key": "value"\n}'
            spellCheck={false}
          />
        </div>
      </div>
      <div className="pane">
        <div className="pane-header">
          <span className="pane-title">Output</span>
          <button className="btn btn-ghost btn-sm" onClick={handleCopy}>≡ƒôï Copy</button>
        </div>
        <div className="pane-body">
          {error && (
            <div style={{
              color: '#ef4444',
              backgroundColor: 'rgba(239,68,68,0.1)',
              border: '1px solid rgba(239,68,68,0.3)',
              borderRadius: '6px',
              padding: '10px 14px',
              marginBottom: '10px',
              fontSize: '13px',
              fontFamily: 'monospace',
              wordBreak: 'break-word'
            }}>
              Γ¥î {error}
            </div>
          )}
          <pre className="code-output">{output || 'Formatted JSON will appear here...'}</pre>
        </div>
        </div>
      </div>

      {/* SEO & Info Section */}
      <div className="seo-content" style={{ marginTop: '20px', padding: '20px', background: 'var(--bg-surface)', borderRadius: 'var(--radius-lg)', border: '1px solid var(--border-primary)', color: 'var(--text-secondary)' }}>
        <h2 style={{ color: 'var(--text-heading)', marginBottom: '16px', fontSize: '1.5rem' }}>JSON Formatter & Validator Guide</h2>

        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(300px, 1fr))', gap: '20px', marginBottom: '24px' }}>
          <div style={{ background: 'var(--bg-primary)', padding: '16px', borderRadius: 'var(--radius-md)', border: '1px solid var(--border-primary)' }}>
            <h3 style={{ color: 'var(--text-primary)', marginBottom: '8px', fontSize: '1.1rem' }}>Common JSON Errors</h3>
            <ul style={{ fontSize: '14px', lineHeight: 1.6, paddingLeft: '20px', margin: 0 }}>
              <li style={{ marginBottom: '6px' }}><strong>Trailing commas:</strong> <code>{`{"a": 1,}`}</code> is invalid. Remove the last comma.</li>
              <li style={{ marginBottom: '6px' }}><strong>Single quotes:</strong> JSON requires double quotes. <code>{`{'key': 'value'}`}</code> will fail.</li>
              <li style={{ marginBottom: '6px' }}><strong>Unquoted keys:</strong> <code>{`{key: "value"}`}</code> is invalid. Keys must be quoted.</li>
              <li><strong>Comments:</strong> Standard JSON does not support <code>//</code> or <code>/* */</code> comments.</li>
            </ul>
          </div>
          <div style={{ background: 'var(--bg-primary)', padding: '16px', borderRadius: 'var(--radius-md)', border: '1px solid var(--border-primary)' }}>
            <h3 style={{ color: 'var(--text-primary)', marginBottom: '8px', fontSize: '1.1rem' }}>Valid JSON Example</h3>
            <pre style={{ margin: 0, padding: '12px', background: 'var(--bg-elevated)', borderRadius: '6px', fontSize: '12px', overflowX: 'auto', color: 'var(--text-heading)' }}>
{`{
  "user": {
    "id": 104,
    "isActive": true,
    "roles": ["admin", "editor"],
    "preferences": null
  }
}`}
            </pre>
          </div>
        </div>

        <h3 style={{ color: 'var(--text-heading)', marginBottom: '16px', fontSize: '1.2rem' }}>Frequently Asked Questions</h3>
        <div style={{ display: 'flex', flexDirection: 'column', gap: '20px' }}>
          <div>
            <h4 style={{ color: 'var(--text-primary)', marginBottom: '6px', fontSize: '1.05rem' }}>Is my JSON data safe?</h4>
            <p style={{ fontSize: '14px', lineHeight: 1.6 }}>Yes, absolutely! Our JSON Formatter runs <strong>100% locally in your web browser</strong>. Your data is never uploaded to any server or database, making it perfectly safe for sensitive configuration files or API tokens.</p>
          </div>
          <div>
            <h4 style={{ color: 'var(--text-primary)', marginBottom: '6px', fontSize: '1.05rem' }}>What is the difference between JSON beautify and minify?</h4>
            <p style={{ fontSize: '14px', lineHeight: 1.6 }}><strong>Beautifying</strong> JSON adds indentation and line breaks to make it readable by humans. <strong>Minifying</strong> JSON removes all unnecessary whitespace to make the payload size as small as possible for network transfers.</p>
          </div>
          <div>
            <h4 style={{ color: 'var(--text-primary)', marginBottom: '6px', fontSize: '1.05rem' }}>How do I fix "Unexpected token" in JSON?</h4>
            <p style={{ fontSize: '14px', lineHeight: 1.6 }}>The "Unexpected token" error usually means you have a syntax issue. Check for trailing commas, ensure all keys and string values are wrapped in double quotes (<code>"</code>), and verify all brackets <code>[]</code> and braces <code>{}</code> are properly closed. Our validator will show you the exact line and column number of the error.</p>
          </div>
        </div>
      </div>
    </div>
  );
}

import React, { useState, useCallback } from 'react';

export default function SqlFormatter({ copyToClipboard, showToast }) {
  const [input, setInput] = useState('');
  const [output, setOutput] = useState('');

  const formatSql = useCallback((sql) => {
    if (!sql.trim()) return '';

    try {
      const indentStr = '  ';

      // Keywords that should appear on their own new line (top-level)
      const majorKeywords = [
        'SELECT', 'FROM', 'WHERE', 'ORDER BY', 'GROUP BY', 'HAVING',
        'LIMIT', 'OFFSET', 'UNION', 'UNION ALL', 'INTERSECT', 'EXCEPT',
        'INSERT INTO', 'INSERT', 'VALUES', 'UPDATE', 'SET', 'DELETE FROM', 'DELETE',
        'CREATE TABLE', 'CREATE INDEX', 'CREATE VIEW', 'CREATE DATABASE',
        'CREATE', 'ALTER TABLE', 'ALTER', 'DROP TABLE', 'DROP INDEX', 'DROP VIEW',
        'DROP DATABASE', 'DROP',
        'LEFT JOIN', 'RIGHT JOIN', 'INNER JOIN', 'OUTER JOIN',
        'LEFT OUTER JOIN', 'RIGHT OUTER JOIN', 'FULL OUTER JOIN',
        'FULL JOIN', 'CROSS JOIN', 'NATURAL JOIN', 'JOIN',
        'ON', 'USING', 'INTO', 'RETURNING'
      ];

      // All SQL keywords to uppercase
      const allKeywords = [
        ...majorKeywords,
        'AND', 'OR', 'NOT', 'IN', 'EXISTS', 'BETWEEN', 'LIKE', 'ILIKE',
        'IS', 'NULL', 'IS NOT', 'IS NULL', 'IS NOT NULL',
        'AS', 'ASC', 'DESC', 'DISTINCT', 'ALL', 'ANY', 'SOME',
        'CASE', 'WHEN', 'THEN', 'ELSE', 'END',
        'IF', 'BEGIN', 'COMMIT', 'ROLLBACK', 'SAVEPOINT',
        'GRANT', 'REVOKE', 'TRUNCATE', 'EXPLAIN', 'ANALYZE',
        'PRIMARY KEY', 'FOREIGN KEY', 'REFERENCES', 'CONSTRAINT',
        'DEFAULT', 'CHECK', 'UNIQUE', 'INDEX', 'CASCADE',
        'ADD', 'COLUMN', 'TABLE', 'DATABASE', 'VIEW',
        'COUNT', 'SUM', 'AVG', 'MIN', 'MAX',
        'COALESCE', 'NULLIF', 'CAST',
        'TRUE', 'FALSE',
        'INT', 'INTEGER', 'VARCHAR', 'TEXT', 'BOOLEAN', 'FLOAT',
        'DOUBLE', 'DECIMAL', 'DATE', 'TIMESTAMP', 'SERIAL', 'BIGINT',
        'SMALLINT', 'CHAR', 'NUMERIC', 'REAL',
        'NOT NULL', 'AUTO_INCREMENT', 'IDENTITY',
        'WITH', 'RECURSIVE', 'OVER', 'PARTITION BY', 'ROWS', 'RANGE',
        'FETCH', 'NEXT', 'FIRST', 'LAST', 'ONLY'
      ];

      // Sort keywords by length (longest first) for proper matching
      const sortedKeywords = [...new Set(allKeywords)].sort((a, b) => b.length - a.length);
      const sortedMajorKeywords = [...new Set(majorKeywords)].sort((a, b) => b.length - a.length);

      // Step 1: Normalize whitespace (but preserve strings)
      let normalized = '';
      let inString = false;
      let strChar = '';
      for (let i = 0; i < sql.length; i++) {
        const ch = sql[i];
        if (inString) {
          normalized += ch;
          if (ch === strChar && sql[i + 1] !== strChar) {
            inString = false;
          } else if (ch === strChar && sql[i + 1] === strChar) {
            normalized += sql[i + 1];
            i++;
          }
          continue;
        }
        if (ch === "'" || ch === '"') {
          inString = true;
          strChar = ch;
          normalized += ch;
          continue;
        }
        // Remove single-line comments
        if (ch === '-' && sql[i + 1] === '-') {
          const nlIdx = sql.indexOf('\n', i);
          if (nlIdx !== -1) {
            i = nlIdx;
          } else {
            break;
          }
          continue;
        }
        // Remove multi-line comments
        if (ch === '/' && sql[i + 1] === '*') {
          const endIdx = sql.indexOf('*/', i + 2);
          if (endIdx !== -1) {
            i = endIdx + 1;
          } else {
            break;
          }
          continue;
        }
        if (/\s/.test(ch)) {
          if (normalized.length > 0 && normalized[normalized.length - 1] !== ' ') {
            normalized += ' ';
          }
        } else {
          normalized += ch;
        }
      }
      normalized = normalized.trim();

      // Step 2: Uppercase keywords (preserve strings)
      let uppercased = '';
      let idx = 0;
      inString = false;
      strChar = '';

      while (idx < normalized.length) {
        const ch = normalized[idx];

        if (inString) {
          uppercased += ch;
          if (ch === strChar && normalized[idx + 1] !== strChar) {
            inString = false;
          } else if (ch === strChar && normalized[idx + 1] === strChar) {
            uppercased += normalized[idx + 1];
            idx += 2;
            continue;
          }
          idx++;
          continue;
        }

        if (ch === "'" || ch === '"') {
          inString = true;
          strChar = ch;
          uppercased += ch;
          idx++;
          continue;
        }

        // Try to match a keyword at current position
        let matched = false;
        const remaining = normalized.substring(idx);
        for (const kw of sortedKeywords) {
          const re = new RegExp(`^(${kw.replace(/\s+/g, '\\s+')})(?=[\\s(),;]|$)`, 'i');
          const m = remaining.match(re);
          if (m) {
            // Make sure we're at a word boundary (start or preceded by space/special)
            if (idx === 0 || /[\s(,;]/.test(normalized[idx - 1])) {
              uppercased += kw;
              idx += m[1].length;
              matched = true;
              break;
            }
          }
        }

        if (!matched) {
          uppercased += ch;
          idx++;
        }
      }

      // Step 3: Add newlines before major keywords
      let formatted = uppercased;
      for (const kw of sortedMajorKeywords) {
        // Add newline before the keyword (if not at start)
        const regex = new RegExp(`(?<!^)\\s+(?=${kw.replace(/\s+/g, '\\s+')}(?=[\\s(,;]|$))`, 'gi');
        formatted = formatted.replace(regex, '\n');
      }

      // Step 4: Indent lines after major keywords
      const lines = formatted.split('\n').map(l => l.trim()).filter(l => l.length > 0);
      let result = '';
      const indentKeywords = new Set(['SELECT', 'SET', 'VALUES']);

      for (let i = 0; i < lines.length; i++) {
        const line = lines[i];
        const firstWord = line.split(/[\s(]/)[0].toUpperCase();

        // Check if this line starts with a major keyword
        let isMajor = false;
        for (const kw of sortedMajorKeywords) {
          if (line.toUpperCase().startsWith(kw)) {
            isMajor = true;
            break;
          }
        }

        if (isMajor) {
          result += line + '\n';
        } else {
          result += indentStr + line + '\n';
        }
      }

      return result.trimEnd();
    } catch (e) {
      return 'Error formatting: ' + e.message;
    }
  }, []);

  const handleFormat = () => {
    setOutput(formatSql(input));
  };

  const handleCopy = () => {
    if (!output) {
      showToast('Nothing to copy');
      return;
    }
    copyToClipboard(output);
    showToast('Copied to clipboard!');
  };

  return (
    <div className="split-pane">
      <div className="pane">
        <div className="pane-header">
          <span className="pane-title">SQL Input</span>
          <button className="btn btn-primary btn-sm" onClick={handleFormat}>
            Γ£¿ Format SQL
          </button>
        </div>
        <div className="pane-body">
          <textarea
            className="textarea-code"
            value={input}
            onChange={(e) => setInput(e.target.value)}
            placeholder="Paste your SQL query here...&#10;&#10;SELECT * FROM users WHERE id = 1"
            spellCheck={false}
          />
        </div>
      </div>
      <div className="pane">
        <div className="pane-header">
          <span className="pane-title">Formatted Output</span>
          <button className="btn btn-ghost btn-sm" onClick={handleCopy}>≡ƒôï Copy</button>
        </div>
        <div className="pane-body">
          <pre className="code-output">{output || 'Formatted SQL will appear here...'}</pre>
        </div>
      </div>
    </div>
  );
}

