import React, { useState, useEffect } from 'react';

function fmt(d) {
  return d.toLocaleString('en-US', {
    weekday: 'long', year: 'numeric', month: 'long',
    day: 'numeric', hour: '2-digit', minute: '2-digit', second: '2-digit',
    timeZoneName: 'short'
  });
}

export default function TimestampTool({ copyToClipboard, showToast }) {
  const [now, setNow] = useState(Math.floor(Date.now() / 1000));
  const [tsInput, setTsInput] = useState('');
  const [dtInput, setDtInput] = useState(new Date().toISOString().slice(0, 16));
  const [tsResult, setTsResult] = useState('');
  const [dtResult, setDtResult] = useState('');
  const [tsError, setTsError] = useState('');

  useEffect(() => {
    const id = setInterval(() => setNow(Math.floor(Date.now() / 1000)), 1000);
    return () => clearInterval(id);
  }, []);

  const convertTs = () => {
    const n = Number(tsInput.trim());
    if (!tsInput.trim() || isNaN(n)) { setTsError('Enter a valid Unix timestamp'); setTsResult(''); return; }
    setTsError('');
    const ms = n > 1e10 ? n : n * 1000;
    const d = new Date(ms);
    setTsResult(fmt(d));
  };

  const convertDt = () => {
    const d = new Date(dtInput);
    if (isNaN(d.getTime())) return;
    setDtResult(Math.floor(d.getTime() / 1000).toString());
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 20 }}>
      {/* Live clock */}
      <div style={{ background: 'var(--bg-surface)', border: '1px solid var(--border-primary)', borderRadius: 'var(--radius-lg)', padding: 20, display: 'flex', alignItems: 'center', justifyContent: 'space-between', flexWrap: 'wrap', gap: 12 }}>
        <div>
          <div style={{ fontSize: 11, fontWeight: 700, textTransform: 'uppercase', letterSpacing: '0.5px', color: 'var(--text-muted)', marginBottom: 4 }}>Current Unix Timestamp</div>
          <div style={{ fontFamily: 'var(--font-mono)', fontSize: 32, fontWeight: 800, color: 'var(--accent-purple-light)' }}>{now}</div>
          <div style={{ fontSize: 13, color: 'var(--text-muted)', marginTop: 4 }}>{fmt(new Date(now * 1000))}</div>
        </div>
        <button className="btn btn-secondary" onClick={() => { copyToClipboard(String(now)); showToast('Timestamp copied!'); }}>Copy Current</button>
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 16 }}>
        {/* Unix ΓåÆ Human */}
        <div className="pane">
          <div className="pane-header"><span className="pane-title">Unix ΓåÆ Human Date</span></div>
          <div className="pane-body" style={{ gap: 12 }}>
            <label className="label">Unix Timestamp (seconds or ms)</label>
            <input className="input-field" placeholder="e.g. 1700000000" value={tsInput} onChange={e => setTsInput(e.target.value)} style={{ fontFamily: 'var(--font-mono)' }} />
            {tsError && <div style={{ color: 'var(--accent-rose)', fontSize: 12 }}>{tsError}</div>}
            <button className="btn btn-primary btn-sm" onClick={convertTs}>Convert</button>
            {tsResult && (
              <div style={{ background: 'var(--bg-primary)', border: '1px solid var(--border-primary)', borderRadius: 8, padding: 12 }}>
                <div style={{ fontSize: 14, color: 'var(--accent-cyan-light)', marginBottom: 8 }}>{tsResult}</div>
                <button className="btn btn-ghost btn-sm" onClick={() => { copyToClipboard(tsResult); showToast('Copied!'); }}>Copy</button>
              </div>
            )}
          </div>
        </div>

        {/* Human ΓåÆ Unix */}
        <div className="pane">
          <div className="pane-header"><span className="pane-title">Human Date ΓåÆ Unix</span></div>
          <div className="pane-body" style={{ gap: 12 }}>
            <label className="label">Select Date & Time</label>
            <input type="datetime-local" className="input-field" value={dtInput} onChange={e => setDtInput(e.target.value)} style={{ fontFamily: 'var(--font-mono)' }} />
            <button className="btn btn-primary btn-sm" onClick={convertDt}>Convert</button>
            {dtResult && (
              <div style={{ background: 'var(--bg-primary)', border: '1px solid var(--border-primary)', borderRadius: 8, padding: 12 }}>
                <div style={{ fontFamily: 'var(--font-mono)', fontSize: 22, fontWeight: 800, color: 'var(--accent-purple-light)', marginBottom: 8 }}>{dtResult}</div>
                <button className="btn btn-ghost btn-sm" onClick={() => { copyToClipboard(dtResult); showToast('Copied!'); }}>Copy</button>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

import React, { useState, useMemo } from 'react';

export default function BorderRadiusGen({ copyToClipboard, showToast }) {
  const [linked, setLinked] = useState(true);
  const [unit, setUnit] = useState('px');
  const [corners, setCorners] = useState({
    topLeft: 16,
    topRight: 16,
    bottomRight: 16,
    bottomLeft: 16,
  });

  const maxVal = unit === 'px' ? 100 : 50;

  const setCorner = (key, value) => {
    if (linked) {
      setCorners({
        topLeft: value,
        topRight: value,
        bottomRight: value,
        bottomLeft: value,
      });
    } else {
      setCorners((prev) => ({ ...prev, [key]: value }));
    }
  };

  const borderRadiusValue = useMemo(() => {
    const { topLeft, topRight, bottomRight, bottomLeft } = corners;
    const u = unit;
    if (topLeft === topRight && topRight === bottomRight && bottomRight === bottomLeft) {
      return `${topLeft}${u}`;
    }
    return `${topLeft}${u} ${topRight}${u} ${bottomRight}${u} ${bottomLeft}${u}`;
  }, [corners, unit]);

  const cssCode = `border-radius: ${borderRadiusValue};`;

  const handleCopy = () => {
    try {
      copyToClipboard(cssCode);
      showToast('Border radius CSS copied!');
    } catch {
      showToast('Failed to copy');
    }
  };

  const cornerEntries = [
    { key: 'topLeft', label: 'Top Left' },
    { key: 'topRight', label: 'Top Right' },
    { key: 'bottomRight', label: 'Bottom Right' },
    { key: 'bottomLeft', label: 'Bottom Left' },
  ];

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
      <div className="split-pane">
          {/* Controls */}
          <div className="pane">
            <div className="pane-header">
              <span className="pane-title">Controls</span>
            </div>
            <div className="pane-body" style={{ gap: '16px' }}>
              {/* Unit toggle + Link toggle */}
              <div style={{ display: 'flex', gap: '16px', alignItems: 'center', justifyContent: 'space-between' }}>
                <div>
                  <label className="label">Unit</label>
                  <div className="tab-group">
                    <button
                      className={`tab-btn ${unit === 'px' ? 'active' : ''}`}
                      onClick={() => setUnit('px')}
                    >
                      px
                    </button>
                    <button
                      className={`tab-btn ${unit === '%' ? 'active' : ''}`}
                      onClick={() => setUnit('%')}
                    >
                      %
                    </button>
                  </div>
                </div>
                <div>
                  <label className="label">Link Corners</label>
                  <label className="checkbox-label">
                    <input
                      type="checkbox"
                      checked={linked}
                      onChange={(e) => setLinked(e.target.checked)}
                    />
                    {linked ? '≡ƒöù Linked' : '≡ƒöô Unlinked'}
                  </label>
                </div>
              </div>

              {/* Corner Sliders */}
              {cornerEntries.map(({ key, label }) => (
                <div className="slider-group" key={key}>
                  <div className="slider-label">
                    <span className="slider-label-text">{label}</span>
                    <span className="slider-value">
                      {corners[key]}{unit}
                    </span>
                  </div>
                  <input
                    type="range"
                    className="slider"
                    min="0"
                    max={maxVal}
                    value={corners[key]}
                    onChange={(e) => setCorner(key, Number(e.target.value))}
                  />
                </div>
              ))}
            </div>
          </div>

          {/* Preview + Output */}
          <div className="pane">
            <div className="pane-header">
              <span className="pane-title">Preview</span>
            </div>
            <div className="pane-body" style={{ gap: '16px' }}>
              {/* Preview Box */}
              <div
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  minHeight: '300px',
                  background: 'var(--bg-primary)',
                  borderRadius: 'var(--radius-md)',
                  border: '1px solid var(--border-primary)',
                }}
              >
                <div
                  style={{
                    width: '200px',
                    height: '200px',
                    background: 'var(--gradient-purple-cyan)',
                    borderRadius: borderRadiusValue,
                    transition: 'border-radius 0.2s ease',
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                  }}
                >
                  <span style={{ color: '#fff', fontFamily: 'var(--font-mono)', fontSize: '13px', fontWeight: 600 }}>
                    {borderRadiusValue}
                  </span>
                </div>
              </div>

              {/* Corner Values Display */}
              <div className="stats-row">
                {cornerEntries.map(({ key, label }) => (
                  <div className="stat-card" key={key}>
                    <div className="stat-value" style={{ fontSize: '18px' }}>
                      {corners[key]}{unit}
                    </div>
                    <div className="stat-label">{label}</div>
                  </div>
                ))}
              </div>

              {/* CSS Output */}
              <div>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '8px' }}>
                  <span className="label" style={{ margin: 0 }}>Generated CSS</span>
                  <button className="btn btn-primary btn-sm" onClick={handleCopy}>
                    ≡ƒôï Copy CSS
                  </button>
                </div>
                <pre className="code-output">{cssCode}</pre>
              </div>
            </div>
          </div>
        </div>
    </div>
  );
}

import React, { useState, useMemo } from 'react';

function hexToRgb(hex) {
  const result = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex);
  return result
    ? { r: parseInt(result[1], 16), g: parseInt(result[2], 16), b: parseInt(result[3], 16) }
    : { r: 0, g: 0, b: 0 };
}

const defaultShadow = () => ({
  id: Date.now(),
  hOffset: 4,
  vOffset: 4,
  blur: 10,
  spread: 0,
  color: '#000000',
  opacity: 0.25,
  inset: false,
});

export default function BoxShadowGen({ copyToClipboard, showToast }) {
  const [shadows, setShadows] = useState([defaultShadow()]);

  const updateShadow = (id, field, value) => {
    setShadows((prev) =>
      prev.map((s) => (s.id === id ? { ...s, [field]: value } : s))
    );
  };

  const addShadow = () => {
    setShadows((prev) => [...prev, { ...defaultShadow(), id: Date.now() + Math.random() }]);
  };

  const removeShadow = (id) => {
    if (shadows.length <= 1) {
      showToast('At least one shadow is required');
      return;
    }
    setShadows((prev) => prev.filter((s) => s.id !== id));
  };

  const shadowStrings = useMemo(() => {
    return shadows.map((s) => {
      const rgb = hexToRgb(s.color);
      const insetStr = s.inset ? 'inset ' : '';
      return `${insetStr}${s.hOffset}px ${s.vOffset}px ${s.blur}px ${s.spread}px rgba(${rgb.r}, ${rgb.g}, ${rgb.b}, ${s.opacity})`;
    });
  }, [shadows]);

  const cssValue = useMemo(() => shadowStrings.join(',\n    '), [shadowStrings]);
  const cssCode = useMemo(() => `box-shadow: ${cssValue};`, [cssValue]);

  const handleCopy = () => {
    try {
      copyToClipboard(cssCode);
      showToast('Box shadow CSS copied!');
    } catch {
      showToast('Failed to copy');
    }
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
      <div className="split-pane">
          {/* Controls */}
          <div className="pane">
            <div className="pane-header">
              <span className="pane-title">Shadows</span>
              <button className="btn btn-secondary btn-sm" onClick={addShadow}>
                + Add Shadow
              </button>
            </div>
            <div className="pane-body" style={{ gap: '16px', overflowY: 'auto', maxHeight: '600px' }}>
              {shadows.map((shadow, index) => (
                <div
                  key={shadow.id}
                  style={{
                    background: 'var(--bg-primary)',
                    border: '1px solid var(--border-primary)',
                    borderRadius: 'var(--radius-sm)',
                    padding: '14px',
                  }}
                >
                  <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '12px' }}>
                    <span style={{ fontSize: '12px', fontWeight: 700, color: 'var(--text-secondary)', textTransform: 'uppercase', letterSpacing: '0.5px' }}>
                      Shadow {index + 1}
                    </span>
                    <button
                      className="btn btn-ghost btn-sm"
                      onClick={() => removeShadow(shadow.id)}
                      style={{ padding: '2px 8px', fontSize: '14px' }}
                    >
                      Γ£ò
                    </button>
                  </div>

                  <div style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
                    {/* H-Offset */}
                    <div className="slider-group">
                      <div className="slider-label">
                        <span className="slider-label-text">H-Offset</span>
                        <span className="slider-value">{shadow.hOffset}px</span>
                      </div>
                      <input
                        type="range" className="slider" min="-50" max="50"
                        value={shadow.hOffset}
                        onChange={(e) => updateShadow(shadow.id, 'hOffset', Number(e.target.value))}
                      />
                    </div>

                    {/* V-Offset */}
                    <div className="slider-group">
                      <div className="slider-label">
                        <span className="slider-label-text">V-Offset</span>
                        <span className="slider-value">{shadow.vOffset}px</span>
                      </div>
                      <input
                        type="range" className="slider" min="-50" max="50"
                        value={shadow.vOffset}
                        onChange={(e) => updateShadow(shadow.id, 'vOffset', Number(e.target.value))}
                      />
                    </div>

                    {/* Blur */}
                    <div className="slider-group">
                      <div className="slider-label">
                        <span className="slider-label-text">Blur</span>
                        <span className="slider-value">{shadow.blur}px</span>
                      </div>
                      <input
                        type="range" className="slider" min="0" max="100"
                        value={shadow.blur}
                        onChange={(e) => updateShadow(shadow.id, 'blur', Number(e.target.value))}
                      />
                    </div>

                    {/* Spread */}
                    <div className="slider-group">
                      <div className="slider-label">
                        <span className="slider-label-text">Spread</span>
                        <span className="slider-value">{shadow.spread}px</span>
                      </div>
                      <input
                        type="range" className="slider" min="-50" max="50"
                        value={shadow.spread}
                        onChange={(e) => updateShadow(shadow.id, 'spread', Number(e.target.value))}
                      />
                    </div>

                    {/* Opacity */}
                    <div className="slider-group">
                      <div className="slider-label">
                        <span className="slider-label-text">Opacity</span>
                        <span className="slider-value">{shadow.opacity}</span>
                      </div>
                      <input
                        type="range" className="slider" min="0" max="1" step="0.01"
                        value={shadow.opacity}
                        onChange={(e) => updateShadow(shadow.id, 'opacity', Number(e.target.value))}
                      />
                    </div>

                    {/* Color + Inset */}
                    <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: '12px' }}>
                      <div className="color-picker-wrapper">
                        <input
                          type="color"
                          className="color-picker"
                          value={shadow.color}
                          onChange={(e) => updateShadow(shadow.id, 'color', e.target.value)}
                          style={{ width: '32px', height: '32px' }}
                        />
                        <span style={{ fontFamily: 'var(--font-mono)', fontSize: '12px', color: 'var(--text-secondary)' }}>
                          {shadow.color}
                        </span>
                      </div>
                      <label className="checkbox-label">
                        <input
                          type="checkbox"
                          checked={shadow.inset}
                          onChange={(e) => updateShadow(shadow.id, 'inset', e.target.checked)}
                        />
                        Inset
                      </label>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </div>

          {/* Preview + Output */}
          <div className="pane">
            <div className="pane-header">
              <span className="pane-title">Preview</span>
            </div>
            <div className="pane-body" style={{ gap: '16px' }}>
              {/* Preview */}
              <div
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  minHeight: '280px',
                  background: 'var(--bg-primary)',
                  borderRadius: 'var(--radius-md)',
                  border: '1px solid var(--border-primary)',
                }}
              >
                <div
                  style={{
                    width: '180px',
                    height: '180px',
                    background: 'var(--bg-surface)',
                    borderRadius: '16px',
                    boxShadow: shadowStrings.join(', '),
                    transition: 'box-shadow 0.2s ease',
                  }}
                />
              </div>

              {/* CSS Output */}
              <div>
