  const canvasRef = useRef();

  useEffect(() => {
    if (!text.trim()) { setError('Enter text or URL'); return; }
    setError('');
    QRCode.toCanvas(canvasRef.current, text, {
      width: size,
      color: { dark: fgColor, light: bgColor },
