import React, { useMemo } from 'react';
import { TOOLS } from '../../App';
import { ToolCard } from '../Landing';

export default function RelatedTools({ currentToolId, onSelect, favorites, toggleFavorite, usageCount }) {
  const related = useMemo(() => {
    const current = TOOLS.find(t => t.id === currentToolId);
    if (!current) return [];

    // Find tools in the same category, excluding the current tool
    const sameCategory = TOOLS.filter(t => t.category === current.category && t.id !== currentToolId);

    // Shuffle and pick up to 3 tools
    const shuffled = [...sameCategory].sort(() => 0.5 - Math.random());
    return shuffled.slice(0, 3);
  }, [currentToolId]);

  if (related.length === 0) return null;

  return (
    <div className="related-tools" style={{ marginTop: '40px', paddingTop: '30px', borderTop: '1px solid var(--border-secondary)' }}>
      <h3 style={{ marginBottom: '20px', color: 'var(--text-heading)', fontSize: '1.2rem' }}>Related {related[0].category} Tools</h3>
      <div className="tools-grid" style={{ gridTemplateColumns: 'repeat(auto-fill, minmax(280px, 1fr))' }}>
        {related.map((tool, i) => (
          <ToolCard
            key={tool.id}
            tool={tool}
            onSelect={onSelect}
            isFavorite={favorites.includes(tool.id)}
            onToggleFavorite={toggleFavorite}
            usageCount={usageCount[tool.id] || 0}
            visible={true}
            index={i}
          />
        ))}
      </div>
    </div>
  );
}

import { useState, useRef, useCallback } from 'react';
import { PDFDocument } from 'pdf-lib';

function formatSize(bytes) {
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
  return `${(bytes / (1024 * 1024)).toFixed(2)} MB`;
}

function calcSaving(original, compressed) {
  if (!original || !compressed) return null;
  const diff = original - compressed;
  const pct = ((diff / original) * 100).toFixed(1);
  return { diff, pct, saved: diff > 0 };
}

const QUALITY_MODES = [
  {
    id: 'screen',
    label: '≡ƒô║ Screen (72 DPI)',
    desc: 'Smallest file ┬╖ Web & email sharing',
    removeMetadata: true,
    removeThumbnails: true,
    removeJS: true,
    objectStreams: true,
  },
  {
    id: 'ebook',
    label: '≡ƒôÜ Ebook (150 DPI)',
    desc: 'Balanced size & quality ┬╖ eReaders',
    removeMetadata: true,
    removeThumbnails: true,
    removeJS: false,
    objectStreams: true,
  },
  {
    id: 'print',
    label: '≡ƒû¿∩╕Å Print (300 DPI)',
    desc: 'Larger file ┬╖ Preserve print quality',
    removeMetadata: true,
    removeThumbnails: false,
    removeJS: false,
