function LockTab({ showToast }) {
  const [file, setFile] = useState(null);
  const [isDragging, setIsDragging] = useState(false);
  const [userPassword, setUserPassword] = useState('');
  const [ownerPassword, setOwnerPassword] = useState('');
  const [isLocking, setIsLocking] = useState(false);
  const fileInputRef = useRef(null);

  const loadFile = useCallback((f) => {
    if (!(f.type === 'application/pdf' || f.name.toLowerCase().endsWith('.pdf'))) {
      showToast('Please upload a valid PDF file.', 'error');
      return;
    }
    setFile(f);
  }, [showToast]);

  const handleDrop = useCallback((e) => {
    e.preventDefault();
    setIsDragging(false);
    const f = e.dataTransfer.files[0];
    if (f) loadFile(f);
  }, [loadFile]);

  const handleFileInput = (e) => {
    if (e.target.files?.[0]) loadFile(e.target.files[0]);
    e.target.value = '';
  };

  const lockPdf = async () => {
    if (!file) return;
    if (!userPassword.trim()) {
      showToast('Please enter a user password.', 'error');
      return;
    }
    setIsLocking(true);
    try {
      const bytes = await file.arrayBuffer();
      const pdfDoc = await PDFDocument.load(bytes, { ignoreEncryption: true });
      const saveOptions = {
        userPassword: userPassword,
      };
      if (ownerPassword.trim()) {
        saveOptions.ownerPassword = ownerPassword;
      }
      const outBytes = await pdfDoc.save(saveOptions);
      const blob = new Blob([outBytes], { type: 'application/pdf' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `locked_${file.name}`;
      a.click();
      URL.revokeObjectURL(url);
      showToast('PDF locked and downloaded! ≡ƒöÆ', 'success');
