import React, { useState, useEffect } from 'react';

function toWords(str) {
  return str
    .replace(/([a-z])([A-Z])/g, '$1 $2')
    .replace(/[_\-]+/g, ' ')
    .split(/\s+/)
    .filter(Boolean);
}

function toUpperCase(str) {
  return str.toUpperCase();
}

function toLowerCase(str) {
  return str.toLowerCase();
}

function toTitleCase(str) {
  return toWords(str)
    .map((w) => w.charAt(0).toUpperCase() + w.slice(1).toLowerCase())
    .join(' ');
}

function toCamelCase(str) {
  const words = toWords(str);
  return words
    .map((w, i) =>
      i === 0 ? w.toLowerCase() : w.charAt(0).toUpperCase() + w.slice(1).toLowerCase()
    )
    .join('');
}

function toPascalCase(str) {
  return toWords(str)
    .map((w) => w.charAt(0).toUpperCase() + w.slice(1).toLowerCase())
    .join('');
}

function toSnakeCase(str) {
  return toWords(str)
    .map((w) => w.toLowerCase())
    .join('_');
}

function toKebabCase(str) {
  return toWords(str)
    .map((w) => w.toLowerCase())
    .join('-');
}

function toConstantCase(str) {
  return toWords(str)
    .map((w) => w.toUpperCase())
    .join('_');
}

function toSentenceCase(str) {
  const lower = str.toLowerCase();
  return lower.charAt(0).toUpperCase() + lower.slice(1);
}

const CONVERSIONS = [
  { label: 'UPPERCASE', fn: toUpperCase },
  { label: 'lowercase', fn: toLowerCase },
  { label: 'Title Case', fn: toTitleCase },
  { label: 'camelCase', fn: toCamelCase },
  { label: 'PascalCase', fn: toPascalCase },
  { label: 'snake_case', fn: toSnakeCase },
  { label: 'kebab-case', fn: toKebabCase },
  { label: 'CONSTANT_CASE', fn: toConstantCase },
  { label: 'Sentence case', fn: toSentenceCase },
];

export default function CaseConverter({ copyToClipboard, showToast, sampleData }) {
  const [input, setInput] = useState('');
  const [output, setOutput] = useState('');
  const [activeConversion, setActiveConversion] = useState('');

  useEffect(() => { if (sampleData) setInput(sampleData); }, [sampleData]);

  const handleConvert = (label, fn) => {
    setActiveConversion(label);
    try {
      setOutput(fn(input));
    } catch {
      setOutput('Error converting text.');
    }
  };

  return (
    <div className="split-pane" style={{ flexDirection: 'column' }}>
      <div className="pane">
        <div className="pane-header">
          <span className="pane-title">Case Converter</span>
        </div>
        <div className="pane-body">
          <label className="label">Input Text</label>
          <textarea
            className="textarea-code"
            value={input}
            onChange={(e) => setInput(e.target.value)}
            placeholder="Enter text to convert..."
            rows={5}
          />
          <div className="btn-group" style={{ marginTop: '0.75rem', flexWrap: 'wrap' }}>
            {CONVERSIONS.map(({ label, fn }) => (
              <button
                key={label}
                className={`btn btn-sm ${activeConversion === label ? 'btn-primary' : 'btn-secondary'}`}
                onClick={() => handleConvert(label, fn)}
                disabled={!input}
              >
                {label}
              </button>
            ))}
          </div>
        </div>
      </div>

      <div className="pane">
        <div className="pane-header">
          <span className="pane-title">
            Output{activeConversion ? ` ΓÇö ${activeConversion}` : ''}
          </span>
          <button
            className="btn btn-primary btn-sm"
            onClick={() => {
              if (output) {
                copyToClipboard(output);
                showToast('Copied to clipboard!');
              }
            }}
            disabled={!output}
          >
            Copy
          </button>
        </div>
        <div className="pane-body">
          <textarea
            className="textarea-code"
            value={output}
            readOnly
            placeholder="Converted text will appear here..."
            rows={5}
          />
        </div>
      </div>
    </div>
  );
}

import React, { useState } from 'react';

function computeDiff(original, modified) {
  const origLines = original.split('\n');
  const modLines = modified.split('\n');
  const maxLen = Math.max(origLines.length, modLines.length);
  const result = [];

  for (let i = 0; i < maxLen; i++) {
    const origLine = i < origLines.length ? origLines[i] : undefined;
    const modLine = i < modLines.length ? modLines[i] : undefined;

    if (origLine === undefined) {
      result.push({ type: 'added', content: modLine, lineNum: i + 1 });
    } else if (modLine === undefined) {
      result.push({ type: 'removed', content: origLine, lineNum: i + 1 });
    } else if (origLine === modLine) {
      result.push({ type: 'same', content: origLine, lineNum: i + 1 });
    } else {
      result.push({ type: 'removed', content: origLine, lineNum: i + 1 });
      result.push({ type: 'added', content: modLine, lineNum: i + 1 });
    }
  }

  return result;
}

export default function DiffChecker({ copyToClipboard, showToast }) {
  const [original, setOriginal] = useState('');
  const [modified, setModified] = useState('');
  const [diffResult, setDiffResult] = useState(null);

  const handleCompare = () => {
    const result = computeDiff(original, modified);
    setDiffResult(result);
  };

  const getClassName = (type) => {
    switch (type) {
      case 'added': return 'diff-line diff-added';
      case 'removed': return 'diff-line diff-removed';
      default: return 'diff-line diff-same';
    }
  };

  const getPrefix = (type) => {
    switch (type) {
      case 'added': return '+';
      case 'removed': return '-';
      default: return ' ';
    }
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '0.5rem', height: '100%' }}>
      <div className="split-pane">
        <div className="pane">
          <div className="pane-header">
            <span className="pane-title">Original</span>
          </div>
          <div className="pane-body">
            <textarea
              className="textarea-code"
              value={original}
              onChange={(e) => setOriginal(e.target.value)}
              placeholder="Paste original text here..."
              rows={10}
            />
          </div>
        </div>
        <div className="pane">
          <div className="pane-header">
            <span className="pane-title">Modified</span>
          </div>
          <div className="pane-body">
            <textarea
              className="textarea-code"
              value={modified}
              onChange={(e) => setModified(e.target.value)}
              placeholder="Paste modified text here..."
              rows={10}
            />
          </div>
        </div>
      </div>

      <div style={{ display: 'flex', justifyContent: 'center' }}>
        <button className="btn btn-primary" onClick={handleCompare}>
          Compare
        </button>
      </div>

      {diffResult && (
        <div className="pane">
          <div className="pane-header">
            <span className="pane-title">
              Diff Result ΓÇö {diffResult.filter((d) => d.type === 'added').length} additions, {diffResult.filter((d) => d.type === 'removed').length} removals
            </span>
          </div>
          <div className="pane-body">
            <div className="code-output" style={{ maxHeight: '400px', overflowY: 'auto' }}>
              {diffResult.map((line, i) => (
                <div key={i} className={getClassName(line.type)}>
                  <span style={{ opacity: 0.5, marginRight: '0.5rem', userSelect: 'none' }}>
                    {getPrefix(line.type)}
                  </span>
                  {line.content}
                </div>
              ))}
              {diffResult.length === 0 && (
                <div style={{ opacity: 0.5, padding: '1rem', textAlign: 'center' }}>
                  No differences found.
                </div>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

