import React, { useState, useEffect } from 'react';

export default function UrlEncodeTool({ copyToClipboard, showToast, sampleData }) {
  const [activeTab, setActiveTab] = useState('encode');
  const [input, setInput] = useState('');
  const [output, setOutput] = useState('');
  const [error, setError] = useState('');

  useEffect(() => { if (sampleData) handleProcess(sampleData, 'encode'); }, [sampleData]);

  const handleProcess = (text, mode) => {
    setInput(text);
    setError('');
    if (!text) {
      setOutput('');
      return;
    }
    try {
      if (mode === 'encode') {
        setOutput(encodeURIComponent(text));
      } else {
        setOutput(decodeURIComponent(text));
      }
    } catch (e) {
      setError(mode === 'encode' ? 'Failed to encode input.' : 'Invalid URL-encoded string.');
      setOutput('');
    }
  };

  const handleTabChange = (tab) => {
    setActiveTab(tab);
    setInput('');
    setOutput('');
    setError('');
  };

  return (
    <div className="split-pane" style={{ flexDirection: 'column' }}>
      <div className="pane">
        <div className="pane-header">
          <span className="pane-title">URL {activeTab === 'encode' ? 'Encoder' : 'Decoder'}</span>
          <div className="tab-group">
            <button
              className={`tab-btn ${activeTab === 'encode' ? 'active' : ''}`}
              onClick={() => handleTabChange('encode')}
            >
              Encode
            </button>
            <button
              className={`tab-btn ${activeTab === 'decode' ? 'active' : ''}`}
              onClick={() => handleTabChange('decode')}
            >
              Decode
            </button>
          </div>
        </div>
        <div className="pane-body">
          <label className="label">
            {activeTab === 'encode' ? 'Text to Encode' : 'URL-encoded String to Decode'}
          </label>
          <textarea
            className="textarea-code"
            value={input}
            onChange={(e) => handleProcess(e.target.value, activeTab)}
            placeholder={activeTab === 'encode' ? 'Enter text to URL-encode...' : 'Enter URL-encoded string to decode...'}
            rows={6}
          />
        </div>
      </div>
      <div className="pane">
        <div className="pane-header">
          <span className="pane-title">Output</span>
          <button
            className="btn btn-primary btn-sm"
            onClick={() => {
              if (output) {
                copyToClipboard(output);
                showToast('Copied to clipboard!');
              }
            }}
            disabled={!output}
          >
            Copy
          </button>
        </div>
        <div className="pane-body">
          {error && <div style={{ color: 'var(--red)', marginBottom: '0.5rem' }}>{error}</div>}
          <textarea
            className="textarea-code"
            value={output}
            readOnly
            placeholder="Output will appear here..."
            rows={6}
          />
        </div>
      </div>
    </div>
  );
}

import React, { useState } from 'react';

function generateUUIDv4() {
  if (typeof crypto !== 'undefined' && crypto.randomUUID) {
    return crypto.randomUUID();
  }
  // Manual fallback
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
    const r = (Math.random() * 16) | 0;
    const v = c === 'x' ? r : (r & 0x3) | 0x8;
    return v.toString(16);
  });
}

export default function UuidGenerator({ copyToClipboard, showToast }) {
  const [uuids, setUuids] = useState([]);
  const [count, setCount] = useState(1);
  const [uppercase, setUppercase] = useState(false);

  const generate = () => {
    const clamped = Math.min(100, Math.max(1, count || 1));
    const generated = [];
    for (let i = 0; i < clamped; i++) {
      generated.push(generateUUIDv4());
    }
    setUuids(generated);
  };

  const formatUuid = (uuid) => (uppercase ? uuid.toUpperCase() : uuid.toLowerCase());

  const formattedUuids = uuids.map(formatUuid);

  return (
    <div className="split-pane" style={{ flexDirection: 'column' }}>
      <div className="pane">
        <div className="pane-header">
          <span className="pane-title">UUID v4 Generator</span>
        </div>
        <div className="pane-body">
          <div className="controls-grid">
            <div>
              <label className="label">Count (1ΓÇô100)</label>
              <input
                className="input-field"
                type="number"
                min={1}
                max={100}
                value={count}
                onChange={(e) => setCount(parseInt(e.target.value, 10) || 1)}
              />
            </div>
            <div>
              <label className="label">Format</label>
              <div className="checkbox-group">
                <label className="checkbox-label">
                  <input
                    type="checkbox"
                    checked={uppercase}
                    onChange={(e) => setUppercase(e.target.checked)}
                  />
                  Uppercase
                </label>
              </div>
            </div>
          </div>
          <div className="btn-group" style={{ marginTop: '0.75rem' }}>
            <button className="btn btn-primary" onClick={generate}>
              Generate
            </button>
            <button
              className="btn btn-secondary"
              onClick={() => {
                if (formattedUuids.length > 0) {
                  copyToClipboard(formattedUuids.join('\n'));
                  showToast('All UUIDs copied!');
                }
              }}
              disabled={formattedUuids.length === 0}
            >
              Copy All
            </button>
          </div>
        </div>
      </div>

      {formattedUuids.length > 0 && (
        <div className="pane">
          <div className="pane-header">
            <span className="pane-title">Generated UUIDs ({formattedUuids.length})</span>
          </div>
          <div className="pane-body">
            <div className="code-output" style={{ maxHeight: '400px', overflowY: 'auto' }}>
              {formattedUuids.map((uuid, i) => (
                <div
                  key={i}
                  style={{
                    display: 'flex',
                    justifyContent: 'space-between',
                    alignItems: 'center',
                    padding: '0.25rem 0',
                    borderBottom: '1px solid var(--border)',
                  }}
                >
                  <code>{uuid}</code>
                  <button
                    className="btn btn-ghost btn-sm"
                    onClick={() => {
                      copyToClipboard(uuid);
                      showToast('UUID copied!');
                    }}
                  >
                    Copy
                  </button>
                </div>
              ))}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

import React, { useState, useMemo, useEffect } from 'react';

export default function WordCounter({ copyToClipboard, showToast, sampleData }) {
  const [text, setText] = useState('');

  useEffect(() => { if (sampleData) setText(sampleData); }, [sampleData]);


  const stats = useMemo(() => {
    const characters = text.length;
    const charactersNoSpaces = text.replace(/\s/g, '').length;

    // Smart word counting using Unicode property escapes
    // Matches letters, numbers, marks, and allows internal hyphens/apostrophes
    const wordMatches = text.match(/[\p{L}\p{N}\p{M}]+(?:[-'ΓÇÖ][\p{L}\p{N}\p{M}]+)*/gu) || [];
    const words = wordMatches.length;

    // Improved sentence counting
    const sentences = text.trim() === '' ? 0 : text.split(/[.!?]+(?:[\s"ΓÇ¥')\]]*)/).filter((s) => s.trim().length > 0).length;

    const paragraphs = text.trim() === '' ? 0 : text.split(/\n\s*\n/).filter((p) => p.trim().length > 0).length;

    // Fix reading time logic (Math.ceil was preventing '< 1 min' from ever showing)
    const readingTimeVal = words / 200;
    let readingTime = '0 min';
    if (words > 0) {
      readingTime = readingTimeVal < 1 ? '< 1 min' : `${Math.ceil(readingTimeVal)} min`;
    }

    return {
      characters,
      charactersNoSpaces,
      words,
      sentences,
      paragraphs,
      readingTime,
    };
  }, [text]);

  return (
    <div className="split-pane" style={{ flexDirection: 'column' }}>
      <div className="pane">
        <div className="pane-header">
          <span className="pane-title">Word Counter</span>
        </div>
        <div className="pane-body">
          <label className="label">Enter your text</label>
          <textarea
            className="textarea-code"
            value={text}
            onChange={(e) => setText(e.target.value)}
            placeholder="Start typing or paste your text here..."
            rows={8}
          />
        </div>
      </div>

      <div className="stats-row">
        <div className="stat-card">
          <div className="stat-value">{stats.charactersNoSpaces}</div>
          <div className="stat-label">Characters</div>
        </div>
        <div className="stat-card">
          <div className="stat-value">{stats.characters}</div>
          <div className="stat-label">With Spaces</div>
        </div>
        <div className="stat-card">
          <div className="stat-value">{stats.words}</div>
          <div className="stat-label">Words</div>
        </div>
        <div className="stat-card">
          <div className="stat-value">{stats.sentences}</div>
          <div className="stat-label">Sentences</div>
        </div>
        <div className="stat-card">
          <div className="stat-value">{stats.paragraphs}</div>
          <div className="stat-label">Paragraphs</div>
        </div>
        <div className="stat-card">
          <div className="stat-value">{stats.readingTime}</div>
          <div className="stat-label">Reading Time</div>
        </div>
      </div>
    </div>
  );
}

